        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def specialFilter(nums):
    def is_first_last_odd(n):
        first = int(str(n)[0])
        last = int(str(n)[-1])
        return first % 2 == 1 and last % 2 == 1

    count = 0
    for num in nums:
        if num > 10 and is_first_last_odd(num):
            count += 1
    return count

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1
    return count

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets or planet2 not in planets:
        return ()
    index1 = planets.index(planet1)
    index2 = planets.index(planet2)
    if index1 < index2:
        return tuple(planets[index1+1:index2])
    else:
        return tuple(planets[index2+1:index1])

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n < 2:
        return y
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return y
    return x

def double_the_difference(lst):
    total = 0
    for num in lst:
        if isinstance(num, int) and num > 0 and num % 2 == 1:
            total += num * num
    return total

def cycpattern_check(a, b):
    """Check if the second word or any of its rotations is a substring in the first word."""
    # Generate all rotations of b
    rotations = [b[i:] + b[:i] for i in range(len(b))]

    # Check if any rotation is a substring of a
    for rotation in rotations:
        if rotation in a:
            return True
    return False

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    even = 0
    odd = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even += 1
        else:
            odd += 1
    return (even, odd)

def int_to_mini_roman(number):
    roman = [
        (1000, 'm'), (900, 'cm'), (500, 'd'), (400, 'cd'),
        (100, 'c'), (90, 'xc'), (50, 'l'), (40, 'xl'),
        (10, 'x'), (9, 'ix'), (5, 'v'), (4, 'iv'), (1, 'i')
    ]
    res = ''
    for value, symbol in roman:
        while number >= value:
            res += symbol
            number -= value
    return res

def find_max(words):
    if not words:
        return ""
    max_chars = 0
    max_word = words[0]
    for word in words:
        unique_chars = len(set(word))
        if unique_chars > max_chars or (unique_chars == max_chars and word < max_word):
            max_chars = unique_chars
            max_word = word
    return max_word

def eat(number, need, remaining):
    total = number + need
    if total <= remaining:
        return [total, remaining - total]
    else:
        return [remaining, 0]

def do_algebra(operator, operand):
    result = operand[0]
    for i in range(len(operator)):
        op = operator[i]
        num = operand[i + 1]
        if op == '+':
            result += num
        elif op == '-':
            result -= num
        elif op == '*':
            result *= num
        elif op == '//':
            result //= num
        elif op == '**':
            result **= num
        else:
            raise ValueError("Invalid operator")
    return result

def solve(s):
    result = []
    for char in s:
        if char.isalpha():
            result.append(char.swapcase())
        else:
            result.append(char)
    return ''.join(result)

import hashlib
def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()

def generate_integers(a, b):
    result = []
    for num in range(a, b + 1):
        for digit in str(num):
            if int(digit) % 2 == 0:
                result.append(int(digit))
    return result
